  const out = {};
  const re = /([^\s=/]+)\s*=\s*(?:"([^"]*)"|'([^']*)')/g;
  let m;
  while ((m = re.exec(raw)) !== null) {
    out[m[1]] = junitDecode(m[2] !== undefined ? m[2] : m[3]);
  }
  return out;
