  writeFileSync(join(stateDir, 'results.json'), JSON.stringify(results, null, 2));
  console.log(`nightly: ${status} at ${sha} (total ${sum.total}, failing ${sum.failing.length}, setup exit ${r.setupCode}, test exit ${r.testCode})`);
