  };
  let m;
  while ((m = tagRe.exec(clean)) !== null) {
    const [, closing, tag, rawAttrs, selfClose] = m;
    if (tag === 'testcase') {
      if (closing) {
        finish();
      } else {
        finish();
        const a = junitAttrs(rawAttrs);
        cur = { name: a.name ?? '', classname: a.classname ?? '', file: a.file || null, status: 'passed' };
        if (selfClose) finish();
      }
    } else if (cur && !closing) {
      if (tag === 'skipped') {
        if (cur.status !== 'failed') cur.status = 'skipped';
      } else {
        cur.status = 'failed';
      }
    }
  }
  finish();
  return cases;
}

function junitFindXml(dir, acc) {
  const entries = readdirSync(dir, { withFileTypes: true });
  entries.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
  for (const e of entries) {
    const p = join(dir, e.name);
    if (e.isDirectory()) junitFindXml(p, acc);
    else if (e.isFile() && e.name.toLowerCase().endsWith('.xml')) acc.push(p);
  }
  return acc;
}

function readJUnitDir(dir) {
  const files = junitFindXml(dir, []);
  if (files.length === 0) throw new Error(`no JUnit XML in ${dir}`);
  const cases = [];
  for (const f of files) cases.push(...parseJUnit(readFileSync(f, 'utf8')));
  return cases;
}

function statusById(cases) {
  const byId = new Map();
  for (const c of cases) {
    const prev = byId.get(c.id);
    if (prev === undefined || c.status === 'failed' || (prev === 'skipped' && c.status === 'passed')) {
      byId.set(c.id, c.status);
    }
  }
  return byId;
}

function summarize(cases) {
  const byId = statusById(cases);
  let skipped = 0;
  const failing = [];
  for (const [id, status] of byId) {
    if (status === 'skipped') skipped++;
    else if (status === 'failed') failing.push(id);
  }
  failing.sort();
  return { total: byId.size, skipped, failing };
}
const EXEC_TAIL = 1048576;

function execTailOfFd(fd) {
  const size = fstatSync(fd).size;
  const len = Math.min(size, EXEC_TAIL);
  const buf = Buffer.alloc(len);
  let off = 0;
  while (off < len) {
    const n = readSync(fd, buf, off, len - off, size - len + off);
    if (n <= 0) break;
    off += n;
  }
  return buf.subarray(0, off).toString('utf8');
}

function sh(cmd, { cwd, env, timeoutMs } = {}) {
  const logPath = join(tmpdir(), `nightly-sh-${process.pid}-${Date.now()}-${Math.random().toString(36).slice(2)}.log`);
  const fd = openSync(logPath, 'w+');
  try {
    const r = spawnSync('bash', ['-c', cmd], {
      cwd,
      env: { ...process.env, ...(env || {}) },
      stdio: ['ignore', fd, fd],
      timeout: timeoutMs,
    });
    const out = execTailOfFd(fd);
    let code;
    if (r.error && r.error.code === 'ETIMEDOUT') code = 124;
    else if (r.error) return { code: 127, out: out + String(r.error.message) };
    else if (r.status !== null) code = r.status;
    else code = 128 + (osConstants.signals[r.signal] || 0);
    return { code, out };
  } finally {
    closeSync(fd);
    rmSync(logPath, { force: true });
  }
}

function git(args, cwd) {
  try {
    return execFileSync('git', ['-c', 'core.hooksPath=/dev/null', ...args], {
      cwd,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
      maxBuffer: 256 * 1024 * 1024,
    });
  } catch (e) {
    const stderr = e.stderr ? String(e.stderr) : '';
    throw new Error(`git ${args.join(' ')} failed: ${stderr.trim() || e.message}`);
  }
}

function repoDir(env) {
  const ws = env.AGENT_WORKSPACE_PATH;
  const full = env.REPO_FULL_NAME;
  if (!ws) throw new Error('AGENT_WORKSPACE_PATH is not set');
  if (!full) throw new Error('REPO_FULL_NAME is not set');
  const name = full.split('/')[1];
  if (!name) throw new Error(`REPO_FULL_NAME has no "/": ${full}`);
  const dir = join(ws, name);
  if (!existsSync(join(dir, '.git'))) throw new Error(`repo not found at ${dir}`);
  return dir;
}

function execTail(s) {
  return s.length > EXEC_TAIL ? s.slice(s.length - EXEC_TAIL) : s;
}

function runSuite({ dir, setup, test, junitDir, timeoutMs }) {
  const jd = resolve(junitDir);
  rmSync(jd, { recursive: true, force: true });
  mkdirSync(jd, { recursive: true });
  let log = '';
  let setupCode = 0;
  if (setup && setup.trim()) {
    const s = sh(setup, { cwd: dir, timeoutMs });
    setupCode = s.code;
    log += `== setup\n${s.out}\n`;
    if (setupCode !== 0) return { setupCode, testCode: null, cases: null, log: execTail(log) };
  }
  const t = sh(test, { cwd: dir, env: { NIGHTLY_JUNIT_DIR: jd }, timeoutMs });
  log += `== test\n${t.out}\n`;
  // A killed run's partial XML must never read as a result.
  let cases = null;
  if (t.code !== 124) {
    try {
      cases = readJUnitDir(jd);
    } catch (e) {
      cases = null;
    }
  }
  return { setupCode, testCode: t.code, cases, log: execTail(log) };
}

function outputJson(obj) {
  const f = process.env.OC_OUTPUT_FILE;
  if (f) writeFileSync(f, JSON.stringify(obj));
}
// GitHub caps issue bodies at 65536 characters; keep the setup log's tail well under it.
const PLAN_SETUP_LOG_MAX = 20000;

function planRead(stateDir, name) {
  const f = join(stateDir, name);
  if (!existsSync(f)) throw new Error(`${f} not found`);
  try {
    return JSON.parse(readFileSync(f, 'utf8'));
  } catch (e) {
    throw new Error(`${f} is not valid JSON: ${e.message}`);
  }
}

function planOpenIssues(raw) {
  if (!Array.isArray(raw)) throw new Error('open-issues.json must be a JSON array');
  return raw.map((i, n) => {
    if (!i || !Number.isInteger(i.number) || !Array.isArray(i.labels)) {
      throw new Error(`open-issues.json entry ${n} needs an integer "number" and a "labels" array`);
    }
    const labels = i.labels.map((l) => (typeof l === 'string' ? l : l && l.name)).filter((l) => typeof l === 'string');
    return { number: i.number, labels, body: typeof i.body === 'string' ? i.body : '' };
  });
}

function planCauses(raw) {
  if (!Array.isArray(raw)) throw new Error('causes.json must be a JSON array');
  raw.forEach((c, n) => {
    const ok = c && typeof c.title === 'string' && c.title.trim() && typeof c.summary === 'string'
      && Array.isArray(c.tests) && c.tests.every((t) => typeof t === 'string') && typeof c.causeCommand === 'string';
    if (!ok) throw new Error(`causes.json entry ${n} needs string "title", "summary", "causeCommand" and a "tests" array of strings`);
  });
  return raw;
}

async function main(env, deps = { outputJson }) {
  if (!env.AGENT_WORKSPACE_PATH) throw new Error('AGENT_WORKSPACE_PATH is not set');
  const stateDir = join(env.AGENT_WORKSPACE_PATH, '.nightly');
  const results = planRead(stateDir, 'results.json');
  const openIssues = planOpenIssues(planRead(stateDir, 'open-issues.json'));
  const setupFailed = results.status === 'setup-failed' ? { log: String(results.log || '').slice(-PLAN_SETUP_LOG_MAX) } : null;
  // Causes only matter on a red night with per-test results; planIssues ignores them otherwise.
  const causes = results.status === 'red' && results.junit ? planCauses(planRead(stateDir, 'causes.json')) : [];
  // Causes that do not partition the failing ids are corrected deterministically; notes say how.
  const { actions, notes } = planIssues({ results, causes, openIssues, setupFailed });
  writeFileSync(join(stateDir, 'plan.json'), JSON.stringify(actions, null, 2));
  console.log(`nightly plan: ${actions.length} action(s): ${actions.map((a) => a.type).join(', ') || 'none'}`);
  for (const n of notes) console.log(`nightly plan note: ${n}`);
  deps.outputJson({ actions: actions.length, notes });
}
await main(process.env);
